public static void main(Args _args)
{
    if (_args && _args.record() is CustTable)
    {
        CustTable custTable = _args.record() as CustTable;

        if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(METCustomerCreatedUpdatedBusinessEvent)))
        {
            METCustomerCreatedUpdatedBusinessEvent::newFromCustTable(custTable, DataEventType::Updated).send();
        }
    }
    else
    {
        throw error(Error::wrongUseOfFunction(funcName()));
    }
}
